<script setup lang="ts">
import { ref } from 'vue';
import { Plus, Search, ClipboardCheck, CheckCircle2 } from '@lucide/vue';
import { useCollection } from '../composables/data';
import { useAuth } from '../stores/auth';
import { api } from '../api/client';
import { checkinFields, checkinPayload } from '../composables/forms';
import { type Offboarding, type Assignment, dateLabel } from '../types';
import AsyncState from '../components/AsyncState.vue';
import StatusBadge from '../components/StatusBadge.vue';
import Pagination from '../components/Pagination.vue';
import FormDialog from '../components/FormDialog.vue';
const { data, loading, error, page, filters, reload } = useCollection<Offboarding>('/offboardings', { active: 'true' }), auth = useAuth(), dialog = ref<InstanceType<typeof FormDialog>>(), success = ref('');
function create() { void dialog.value?.open({ title: '啟動離職交接', description: '系統會即時列出未歸還設備，並停止該員工新增領用。', fields: [{ key: 'employeeId', label: '交接員工', type: 'employee', required: true }, { key: 'plannedLeaveAt', label: '預計離職日期', type: 'date', required: true }, { key: 'notes', label: '交接備註', type: 'textarea' }], submitLabel: '啟動交接', onSubmit: async v => { await api('/offboardings', { method: 'POST', body: v }); success.value = '離職交接已建立。'; await reload(); } }); }
function checkin(a: Assignment) { void dialog.value?.open({ title: '交接設備歸還', description: `${a.asset.assetTag} · ${a.asset.name}`, fields: checkinFields, initial: { condition: 'GOOD' }, submitLabel: '確認歸還', onSubmit: async v => { await api(`/assignments/${a.id}/checkin`, { method: 'POST', body: checkinPayload(v) }); success.value = '設備已歸還，交接清單已重新計算。'; await reload(); } }); }
function complete(o: Offboarding) { void dialog.value?.open({ title: '確認完成離職交接', description: `${o.employee.name} 的設備已全部歸還。伺服器將再次檢查後完成交接並將員工標記為已離職。`, submitLabel: '完成交接', onSubmit: async () => { await api(`/offboardings/${o.id}/complete`, { method: 'POST' }); success.value = '離職交接已完成，歷史紀錄已保留。'; await reload(); } }); }
</script>
<template><div class="page-heading"><div><span class="eyebrow">A THOUGHTFUL HANDOVER</span><h1>離職交接<span class="heading-dot">.</span></h1><p>一份清楚的交接清單，讓每一次告別都妥善完成。</p></div><button v-if="auth.canWrite" class="btn" @click="create"><Plus :size="17" />啟動離職交接</button></div><p v-if="success" class="notice" role="status">{{ success }}</p><section class="panel"><div class="list-toolbar"><div class="search-input"><Search :size="18" /><input v-model="filters.search" type="search" aria-label="搜尋交接員工" placeholder="搜尋交接員工姓名…"></div><select v-model="filters.active" aria-label="交接狀態"><option value="true">交接中</option><option value="false">已完成</option><option value="">所有交接</option></select></div><AsyncState :loading="loading" :error="error" :empty="!data?.items.length" @retry="reload"><div class="offboarding-list"><article v-for="o in data?.items" :key="o.id" class="offboarding-card"><header><span class="avatar">{{ o.employee.name.slice(0, 1) }}</span><div><RouterLink :to="`/employees/${o.employee.id}`"><h2>{{ o.employee.name }}</h2></RouterLink><small>{{ o.employee.department.name }} · 預計離職 {{ dateLabel(o.plannedLeaveAt) }}</small></div><StatusBadge :status="o.completedAt ? 'COMPLETED' : 'OFFBOARDING'" /></header><div class="handover-summary"><ClipboardCheck :size="20" /><span v-if="!o.completedAt">尚有 <strong>{{ o.employee.assignments?.length ?? 0 }}</strong> 項設備待歸還</span><span v-else>交接完成於 {{ dateLabel(o.completedAt) }} · {{ o.completedBy?.name }}</span><span v-if="!o.completedAt" class="muted">歸還後即可完成交接</span></div><div v-for="a in o.employee.assignments" :key="a.id" class="handover-item"><RouterLink :to="`/assets/${a.assetId}`"><strong>{{ a.asset.name }}</strong><small class="mono">{{ a.asset.assetTag }} · {{ dateLabel(a.checkedOutAt) }} 領用</small></RouterLink><button v-if="auth.canWrite && !o.completedAt" class="btn secondary small" @click="checkin(a)">歸還設備</button></div><p v-if="!o.employee.assignments?.length && !o.completedAt" class="all-clear"><CheckCircle2 :size="18" /> 所有設備均已歸還，可以完成交接。</p><p v-if="o.notes" class="record-note">{{ o.notes }}</p><footer v-if="!o.completedAt && auth.canWrite"><span class="muted">{{ o.operator.name }} 啟動於 {{ dateLabel(o.startedAt) }}</span><button class="btn" :disabled="!!o.employee.assignments?.length" @click="complete(o)">完成交接</button></footer></article></div></AsyncState><Pagination v-if="data" v-model:page="page" :total="data.total" /></section><FormDialog ref="dialog" /></template>
